-- Run in Supabase SQL Editor. All records are scoped to the authenticated owner.
create extension if not exists pgcrypto;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text unique not null,emoji text default '🍽️',sort_order int default 0,owner_id uuid not null references auth.users(id) on delete cascade);
create table if not exists public.menu_items(id uuid primary key default gen_random_uuid(),category_name text not null references public.categories(name) on update cascade,name text not null,price numeric(10,2) not null check(price>=0),stock_quantity numeric(10,2) not null default 0,emoji text default '🍽️',active boolean default true,owner_id uuid not null references auth.users(id) on delete cascade,unique(category_name,name,owner_id));
create sequence if not exists public.bill_number_seq;
create or replace function public.generate_bill_number() returns text language plpgsql security definer set search_path=public as $$ begin return 'HC-'||to_char(now(),'YYYYMMDD')||'-'||lpad(nextval('public.bill_number_seq')::text,6,'0'); end; $$;
create table if not exists public.bills(id uuid primary key default gen_random_uuid(),bill_number text unique not null default public.generate_bill_number(),subtotal numeric(12,2) default 0,discount_amount numeric(12,2) default 0,gst_amount numeric(12,2) default 0,total_amount numeric(12,2) default 0,payment_mode text not null check(payment_mode in ('Cash','UPI','Card')),status text default 'Completed',owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.bill_items(id uuid primary key default gen_random_uuid(),bill_id uuid not null references public.bills(id) on delete cascade,menu_item_id uuid references public.menu_items(id) on delete set null,item_name text not null,category_name text not null,unit_price numeric(10,2) not null,quantity int not null check(quantity>0),line_total numeric(12,2) not null);
create table if not exists public.cafe_settings(id uuid primary key default gen_random_uuid(),cafe_name text not null default 'Hypss-Cafe',tagline text,address text,phone text,email text,gst_percent numeric(5,2) default 0,owner_id uuid unique not null references auth.users(id) on delete cascade);
alter table public.categories enable row level security; alter table public.menu_items enable row level security; alter table public.bills enable row level security; alter table public.bill_items enable row level security; alter table public.cafe_settings enable row level security;
drop policy if exists "owner categories" on public.categories; create policy "owner categories" on public.categories for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists "owner menu" on public.menu_items; create policy "owner menu" on public.menu_items for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists "owner bills" on public.bills; create policy "owner bills" on public.bills for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists "owner bill items" on public.bill_items; create policy "owner bill items" on public.bill_items for all to authenticated using(exists(select 1 from public.bills b where b.id=bill_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.bills b where b.id=bill_id and b.owner_id=auth.uid()));
drop policy if exists "owner settings" on public.cafe_settings; create policy "owner settings" on public.cafe_settings for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
grant select,insert,update,delete on public.categories,public.menu_items,public.bills,public.bill_items,public.cafe_settings to authenticated; grant usage,select on sequence public.bill_number_seq to authenticated;
